package com.quincaisoft.identity.application;
import com.quincaisoft.identity.api.*;import com.quincaisoft.identity.infrastructure.*;import com.quincaisoft.audit.api.*;import com.quincaisoft.shared.*;import jakarta.persistence.*;import org.springframework.stereotype.Service;import org.springframework.security.access.AccessDeniedException;import java.util.*;import java.time.*;
@Service public class DefaultIdentityService implements IdentityService {
private final EntityManager em;private final ScopedTransactions tx;private final AuditService audit;public DefaultIdentityService(EntityManager em,ScopedTransactions tx,AuditService audit){this.em=em;this.tx=tx;this.audit=audit;}
private Membership member(UUID actor,LockModeType lock){var s=TenantContext.current();var m=em.find(Membership.class,new Membership.Key(s.tenantId(),actor,s.companyId(),s.branchId()),lock);if(m==null)throw new NoSuchElementException("Membership not found");return m;}
private void owner(){var m=member(TenantContext.current().actorId(),LockModeType.NONE);if(!m.active||!"owner".equals(m.roleCode))throw new AccessDeniedException("Current active branch owner required");}
public List<Member> members(){return tx.execute(()->{owner();return em.createQuery("select m from Membership m order by m.actorId",Membership.class).getResultList().stream().map(m->new Member(m.actorId,m.roleCode,m.active,m.authorizationEpoch)).toList();});}
public List<Change> changes(){return tx.execute(()->{owner();return em.createQuery("select r from MembershipChange r order by r.createdAt desc,r.id",MembershipChange.class).setMaxResults(100).getResultList().stream().map(this::view).toList();});}
public Change request(Request i){if(i==null||i.operationId()==null||i.targetActor()==null||i.reason()==null||i.reason().trim().length()<3||i.reason().length()>2000||!Set.of("owner","manager","finance","inventory","purchasing","cashier","sales","delivery","auditor").contains(i.desiredRole()))throw new IllegalArgumentException("Valid role, identity and reason required");return tx.execute(()->{owner();var s=TenantContext.current();if(s.actorId().equals(i.targetActor()))throw new AccessDeniedException("Cannot change your own membership");
var previous=em.createQuery("select r from MembershipChange r where r.operationId=:o",MembershipChange.class).setParameter("o",i.operationId()).getResultList();if(!previous.isEmpty()){var r=previous.getFirst();if(!r.targetActor.equals(i.targetActor())||!r.requestedBy.equals(s.actorId())||!r.desiredRole.equals(i.desiredRole())||r.desiredActive!=i.desiredActive()||r.expectedEpoch!=i.expectedEpoch()||!r.reason.equals(i.reason().trim()))throw new IllegalStateException("Operation ID reused with different request");return view(r);}
var m=member(i.targetActor(),LockModeType.PESSIMISTIC_WRITE);if(m.authorizationEpoch!=i.expectedEpoch())throw new RevisionConflict("Membership changed");var r=new MembershipChange();r.tenantId=s.tenantId();r.companyId=s.companyId();r.branchId=s.branchId();r.id=UUID.randomUUID();r.operationId=i.operationId();r.targetActor=i.targetActor();r.requestedBy=s.actorId();r.desiredRole=i.desiredRole();r.desiredActive=i.desiredActive();r.expectedEpoch=i.expectedEpoch();r.reason=i.reason().trim();r.status="REQUESTED";r.createdAt=Instant.now();em.persist(r);audit.append(r.operationId,"MembershipChangeRequested","identity",r.id,r.reason);em.flush();return view(r);});}
public Change approve(UUID id,UUID operation,long version){if(operation==null)throw new IllegalArgumentException("Approval operation required");return tx.execute(()->{em.createQuery("select m from Membership m where m.active=true and m.roleCode='owner' order by m.actorId",Membership.class).setLockMode(LockModeType.PESSIMISTIC_WRITE).getResultList();owner();var s=TenantContext.current();var r=em.find(MembershipChange.class,new MembershipChange.Key(s.tenantId(),s.companyId(),id),LockModeType.PESSIMISTIC_WRITE);if(r==null)throw new NoSuchElementException("Change not found");if("APPLIED".equals(r.status)){if(!operation.equals(r.approvalOperation))throw new IllegalStateException("Change already applied by another operation");return view(r);}if(r.requestedBy.equals(s.actorId())||r.targetActor.equals(s.actorId()))throw new AccessDeniedException("Separate owner approval required");if(r.version!=version)throw new RevisionConflict("Change request changed");var m=member(r.targetActor,LockModeType.PESSIMISTIC_WRITE);if(m.authorizationEpoch!=r.expectedEpoch)throw new RevisionConflict("Membership changed since request");r.approvedBy=s.actorId();r.approvalOperation=operation;em.flush();em.createNativeQuery("select set_config('app.identity_change_id',:id,true)").setParameter("id",r.id.toString()).getSingleResult();m.active=r.desiredActive;m.roleCode=r.desiredRole;m.authorizationEpoch=Math.incrementExact(m.authorizationEpoch);em.flush();r.status="APPLIED";audit.append(operation,"MembershipChanged","identity",r.id,r.reason);em.flush();return view(r);});}
private Change view(MembershipChange r){return new Change(r.id,r.operationId,r.targetActor,r.requestedBy,r.approvedBy,r.desiredRole,r.desiredActive,r.expectedEpoch,r.reason,r.status,r.version,r.createdAt);}

public Member current(){return tx.execute(()->{var m=member(TenantContext.current().actorId(),LockModeType.NONE);if(!m.active)throw new AccessDeniedException("Active membership required");return new Member(m.actorId,m.roleCode,m.active,m.authorizationEpoch);});}
public Revocation revoke(Revoke input){if(input==null||input.operationId()==null||input.targetActor()==null||input.reason()==null||input.reason().isBlank()||input.reason().length()>2000)throw new IllegalArgumentException("Revocation identity and reason required");return tx.execute(()->{
 var s=TenantContext.current();var requester=current();if(!s.actorId().equals(input.targetActor())&&!requester.role().equals("owner"))throw new AccessDeniedException("Only own sessions or active owner authority");
 var json=tools.jackson.databind.json.JsonMapper.builder().build();String material="IDENTITY_REVOKE|"+s.actorId()+"|"+input;String hash;try{hash=java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(material.getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(java.security.NoSuchAlgorithmException e){throw new IllegalStateException(e);}
 em.createNativeQuery("select 1 from pg_advisory_xact_lock(hashtextextended(:k,0))").setParameter("k",s.tenantId()+":"+input.operationId()).getSingleResult();
 var prior=em.createNativeQuery("select request_hash,response_json::text,company_id,branch_id from idempotency_result where tenant_id=:t and operation_id=:o").setParameter("t",s.tenantId()).setParameter("o",input.operationId()).getResultList();if(!prior.isEmpty()){Object[] r=(Object[])prior.getFirst();if(!hash.equals(r[0])||!s.companyId().equals(r[2])||!s.branchId().equals(r[3]))throw new IllegalStateException("Operation reused");return json.readValue((String)r[1],Revocation.class);}
 var target=member(input.targetActor(),LockModeType.PESSIMISTIC_WRITE);if(target.authorizationEpoch!=input.expectedEpoch())throw new RevisionConflict("Membership changed");
 var fact=new RevocationRecord();fact.tenantId=s.tenantId();fact.companyId=s.companyId();fact.branchId=s.branchId();fact.id=input.operationId();fact.actorId=s.actorId();fact.targetActor=target.actorId;fact.expectedEpoch=target.authorizationEpoch;fact.reason=input.reason();fact.createdAt=Instant.now();em.persist(fact);em.flush();
 em.createNativeQuery("select set_config('app.revocation_id',:id,true)").setParameter("id",fact.id.toString()).getSingleResult();target.authorizationEpoch=Math.incrementExact(target.authorizationEpoch);em.flush();
 var result=new Revocation(fact.id,target.actorId,target.authorizationEpoch,target.actorId.equals(s.actorId()),"CURRENT_COMPANY_BRANCH_AUTHORIZATION_EPOCH");audit.append(input.operationId(),"AuthorizationEpochRevoked","identity",fact.id,input.reason());
 em.createNativeQuery("insert into idempotency_result(tenant_id,operation_id,company_id,branch_id,request_hash,source_type,source_id,response_json)values(:t,:o,:c,:b,:h,'AUTHORIZATION_REVOCATION',:id,cast(:j as jsonb))").setParameter("t",s.tenantId()).setParameter("o",input.operationId()).setParameter("c",s.companyId()).setParameter("b",s.branchId()).setParameter("h",hash).setParameter("id",fact.id).setParameter("j",json.writeValueAsString(result)).executeUpdate();
 em.createNativeQuery("insert into outbox_event(tenant_id,id,company_id,branch_id,operation_id,event_type,aggregate_type,aggregate_id,payload)values(:t,:e,:c,:b,:o,'AuthorizationEpochRevoked.v1','identity',:id,cast(:j as jsonb))").setParameter("t",s.tenantId()).setParameter("e",UUID.randomUUID()).setParameter("c",s.companyId()).setParameter("b",s.branchId()).setParameter("o",input.operationId()).setParameter("id",fact.id).setParameter("j",json.writeValueAsString(result)).executeUpdate();return result;
 });}
}